DATA:   FILE IS "data\DANDS.dat";
        TYPE IS COVARIANCE;
        NOBSERVATIONS ARE 84;
VARIABLE: NAMES ARE Y1-Y16;
MODEL:    F1 BY Y1* Y2 Y3;
          F2 BY Y4* Y5;
          F3 BY Y6* Y7 Y8;
          F4 BY Y9 Y10 Y11;
          F5 BY Y12 Y13;
          F6 BY Y14 Y15 Y16;
          F1@1; F2@1; F3@1;
          F1 WITH F2-F6;
          F2 WITH F3-F6;
          F3 WITH F4-F6;
          F4 WITH F5-F6;
          F5 WITH F6;
          Y6 WITH Y14;
